def shortestEncodingLength(s):
    n = len(s)
    f = [[0] * n for _ in range(n)]
    for L in range(1, n + 1):
        for i in range(n - L + 1):
            j = i + L - 1
            if L == 1:
                f[i][j] = 1
                continue
            best = L
            fi = f[i]
            for m in range(i, j):
                v = fi[m] + f[m + 1][j]
                if v < best:
                    best = v
            sub = s[i:j + 1]
            idx = (sub + sub).find(sub, 1)
            if idx < L:
                v = len(str(L // idx)) + 2 + f[i][i + idx - 1]
                if v < best:
                    best = v
            f[i][j] = best
    return f[0][n - 1]
